/**
 * Common contract for payout onboarding services.
 *
 * Each supported provider (RazorpayX, Cashfree, Decentro, …) gets its own
 * service module implementing this interface. Use-cases depend only on this
 * interface (via the PAYOUT_ONBOARDING_SERVICE DI token), never on a concrete
 * provider, so adding a platform is a new module directory, not an edit to
 * existing code.
 */
import { Injectable } from "@nestjs/common";

/** Result of initiating a payout-account link. */
export interface PayoutOnboardingInitiateResult {
  /** 'redirect' — expert browser opens a hosted onboarding URL. */
  readonly type: "redirect";
  /** Hosted onboarding URL the expert browser should open. */
  readonly url: string;
  /** One-time state value bound to this link attempt (CSRF + idempotency). */
  readonly state: string;
}

/** Result of initiating a payout-account link via form (no redirect). */
export interface PayoutOnboardingFormResult {
  /** Always 'form' for direct API flows. */
  readonly type: "form";
  /** Field names the frontend should collect from the expert. */
  readonly fields: string[];
  /** Empty string — no redirect URL for form-type flows. */
  readonly url: string;
}

export type PayoutOnboardingInitiateOutput =
  | PayoutOnboardingInitiateResult
  | PayoutOnboardingFormResult;

/** Normalized provider account record returned after a successful link completion. */
export interface PayoutOnboardingLinkedAccount {
  /** Provider account id (e.g. RazorpayX fund_account_id). */
  readonly externalAccountId: string;
  /** Provider access token (encrypted at rest by the caller). */
  readonly accessToken: string;
  /** Provider refresh token (encrypted at rest by the caller). */
  readonly refreshToken?: string;
  /** When the access token expires (ISO string), if known. */
  readonly tokenExpiresAt?: string;
  /** Provider-specific extra payload to store verbatim. */
  readonly raw: Record<string, unknown>;
}

/** Standardized payout-account status fetched from the provider. */
export interface PayoutOnboardingAccountStatus {
  /** Whether the provider account is active and can receive payouts. */
  readonly active: boolean;
  /** Provider-facing status string (e.g. 'active', 'pending', 'rejected'). */
  readonly status: string;
  /** Human-readable failure reason, if any. */
  readonly failureReason?: string;
}

/** Parsed webhook event from a provider. */
export interface PayoutOnboardingWebhookEvent {
  /** Provider account id the event refers to. */
  readonly externalAccountId: string;
  /** Normalized event type (e.g. 'account.activated', 'account.rejected'). */
  readonly eventType: string;
  /** Provider-specific raw event payload. */
  readonly raw: Record<string, unknown>;
}

/** Context passed to a service when initiating a link for a specific expert. */
export interface PayoutOnboardingExpertContext {
  /** Expert's internal id. */
  readonly expertId: number;
  /** Callback URL the provider redirects to after the expert completes
   * onboarding. */
  readonly redirectUri: string;
  /** One-time state value generated by the use-case. */
  readonly state: string;
}

/** Input to initiate onboarding. */
export interface PayoutOnboardingInitiateInput {
  expertId: number;
  redirectUri?: string;
  accountHolderName?: string;
  accountNumber?: string;
  ifsc?: string;
  metadata?: Record<string, unknown>;
}

/** Input to complete onboarding. */
export interface PayoutOnboardingCompleteInput {
  /** OAuth code (redirect providers only) */
  code?: string;
  /** OAuth state (redirect providers only) */
  state?: string;
  /** Bank details (direct API providers only) */
  accountHolderName?: string;
  accountNumber?: string;
  ifsc?: string;
}

/** Output from complete. */
export interface PayoutOnboardingCompleteOutput {
  externalAccountId: string;
  status: "pending" | "active" | "failed";
}

/** Status refresh result. */
export interface PayoutOnboardingStatusResult {
  externalAccountId: string;
  status: "pending" | "active" | "failed" | "unknown";
  lastSyncedAt: Date;
}

/** Generic payout-account onboarding service interface. */
@Injectable()
export abstract class PayoutOnboardingService {
  /** Stable provider key (e.g. 'razorpayx'). */
  abstract readonly provider: string;

  /** Start onboarding. Returns redirect URL or form spec. */
  abstract initiate(
    ctx: PayoutOnboardingExpertContext,
  ): Promise<PayoutOnboardingInitiateOutput>;

  /** Complete the link. */
  abstract complete(
    input: PayoutOnboardingCompleteInput,
  ): Promise<PayoutOnboardingLinkedAccount>;

  /** Fetch the current status of a linked provider account. */
  abstract fetchAccountStatus(ctx: {
    externalAccountId: string;
    accessToken: string;
  }): Promise<PayoutOnboardingAccountStatus>;

  /** Optionally deactivate/revoke a provider account when the expert unlinks. */
  abstract deactivate?(externalAccountId: string): Promise<void>;

  /** Optionally validate a penny-drop amount (direct API flows only). */
  abstract validatePennyDrop?(
    validationId: string,
    amount: number,
  ): Promise<{ validated: boolean }>;

  /** Verify a provider webhook signature and parse it into a normalized event. */
  abstract parseWebhook(
    headers: Record<string, string | string[] | undefined>,
    rawBody: Buffer,
  ): Promise<PayoutOnboardingWebhookEvent | null>;
}

/** DI token for resolving the active payout onboarding service. */
export const PAYOUT_ONBOARDING_SERVICE = "IPayoutOnboardingService";
